-- ==============================================================================
-- HIOps 数据库增量升级补丁 (patch.sql)
-- 适用: 补充 DLP 终端看护、指令下发、网络发现等缺失数据表
-- ==============================================================================

-- 1. 终端鉴权密钥表 (DlpAgentKeys) - 核心缺失表 (Id 为 bigint / Int64)
DROP TABLE IF EXISTS public."DlpAgentKeys" CASCADE;
CREATE TABLE public."DlpAgentKeys" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DeviceId" character varying(256),
    "KeyHash" character varying(128) NOT NULL,
    "Label" character varying(256),
    "CreatedBy" character varying(128),
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "RevokedAt" timestamp with time zone,
    "LastUsedAt" timestamp with time zone
);
CREATE INDEX IF NOT EXISTS "IX_DlpAgentKeys_KeyHash" ON public."DlpAgentKeys" ("KeyHash");

-- 2. 终端远程指令下发与回执表 (DlpCommands) (Id 为 bigint / Int64)
DROP TABLE IF EXISTS public."DlpCommands" CASCADE;
CREATE TABLE public."DlpCommands" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DeviceId" character varying(256),
    "Type" character varying(64),
    "PayloadJson" text,
    "Reason" character varying(1024),
    "CreatedBy" character varying(128),
    "SecondReviewer" character varying(128),
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "ExpiresAt" timestamp with time zone,
    "AckedAt" timestamp with time zone,
    "AckResult" text,
    "IdempotencyKey" character varying(128)
);
CREATE INDEX IF NOT EXISTS "IX_DlpCommands_CreatedAt" ON public."DlpCommands" ("CreatedAt");
CREATE INDEX IF NOT EXISTS "IX_DlpCommands_DeviceId_AckedAt" ON public."DlpCommands" ("DeviceId", "AckedAt");
CREATE INDEX IF NOT EXISTS "IX_DlpCommands_IdempotencyKey" ON public."DlpCommands" ("IdempotencyKey");

-- 3. DLP 事件与策略表
CREATE TABLE IF NOT EXISTS public."DlpEvents" (
    "Id" uuid NOT NULL,
    "OccurredAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "DeviceId" character varying(256),
    "DeviceIp" character varying(64),
    "UserName" character varying(128),
    "Channel" character varying(64),
    "FileName" character varying(512),
    "FileExtension" character varying(64),
    "FileType" character varying(64),
    "SizeBytes" bigint NOT NULL DEFAULT 0,
    "Sha256" character varying(128),
    "HeadHash16" character varying(16),
    "EncodingName" character varying(64),
    "DecodeFailed" boolean NOT NULL DEFAULT FALSE,
    "Records" integer NOT NULL DEFAULT 0,
    "Score" integer NOT NULL DEFAULT 0,
    "Level" character varying(32),
    "HitsJson" text,
    "Notes" text,
    "Source" character varying(64),
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    CONSTRAINT "PK_DlpEvents" PRIMARY KEY ("Id")
);
CREATE INDEX IF NOT EXISTS "IX_DlpEvents_DeviceId_OccurredAt" ON public."DlpEvents" ("DeviceId", "OccurredAt");
CREATE INDEX IF NOT EXISTS "IX_DlpEvents_HeadHash16" ON public."DlpEvents" ("HeadHash16");
CREATE INDEX IF NOT EXISTS "IX_DlpEvents_Level" ON public."DlpEvents" ("Level");
CREATE INDEX IF NOT EXISTS "IX_DlpEvents_OccurredAt" ON public."DlpEvents" ("OccurredAt");

CREATE TABLE IF NOT EXISTS public."DlpPolicies" (
    "Id" uuid NOT NULL,
    "Name" character varying(256),
    "Pattern" character varying(2048),
    "Scope" character varying(64),
    "Reason" character varying(1024),
    "ExemptFromCircuitBreaker" boolean NOT NULL DEFAULT FALSE,
    "Enabled" boolean NOT NULL DEFAULT TRUE,
    "CreatedBy" character varying(128),
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    CONSTRAINT "PK_DlpPolicies" PRIMARY KEY ("Id")
);
CREATE INDEX IF NOT EXISTS "IX_DlpPolicies_Scope_Enabled" ON public."DlpPolicies" ("Scope", "Enabled");

CREATE TABLE IF NOT EXISTS public."DlpFindings" (
    "Id" uuid NOT NULL,
    "EventId" uuid NOT NULL,
    "Title" character varying(256),
    "Level" character varying(32),
    "Status" character varying(32),
    "Owner" character varying(128),
    "Resolution" character varying(1024),
    "EvidenceCapsuleId" character varying(128),
    "SecondReviewer" character varying(128),
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_DlpFindings" PRIMARY KEY ("Id")
);
CREATE INDEX IF NOT EXISTS "IX_DlpFindings_CreatedAt" ON public."DlpFindings" ("CreatedAt");
CREATE INDEX IF NOT EXISTS "IX_DlpFindings_EventId" ON public."DlpFindings" ("EventId");
CREATE INDEX IF NOT EXISTS "IX_DlpFindings_Status" ON public."DlpFindings" ("Status");

-- 4. 研判与溯源辅助表
CREATE TABLE IF NOT EXISTS public."DlpAnalystNotes" (
    "Id" uuid NOT NULL,
    "EventId" uuid NOT NULL,
    "TaskKind" character varying(64),
    "Status" character varying(32),
    "OutboundPayloadJson" text,
    "OutboundHash" character varying(128),
    "GateDecision" character varying(64),
    "GateViolations" text,
    "RuleLevel" character varying(32),
    "RuleScore" integer NOT NULL DEFAULT 0,
    "SuggestedLevel" character varying(32),
    "Confidence" numeric NOT NULL DEFAULT 0,
    "Summary" character varying(4096),
    "SuggestedActions" text,
    "WhitelistSuggestions" text,
    "ModelName" character varying(128),
    "ModelCalled" boolean NOT NULL DEFAULT FALSE,
    "FallbackReason" character varying(512),
    "LatencyMs" integer NOT NULL DEFAULT 0,
    "TakenAt" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "CompletedAt" timestamp with time zone,
    CONSTRAINT "PK_DlpAnalystNotes" PRIMARY KEY ("Id")
);
CREATE INDEX IF NOT EXISTS "IX_DlpAnalystNotes_CreatedAt" ON public."DlpAnalystNotes" ("CreatedAt");
CREATE INDEX IF NOT EXISTS "IX_DlpAnalystNotes_EventId" ON public."DlpAnalystNotes" ("EventId");
CREATE INDEX IF NOT EXISTS "IX_DlpAnalystNotes_Status_Id" ON public."DlpAnalystNotes" ("Status", "Id");

CREATE TABLE IF NOT EXISTS public."DlpFlowRecords" (
    "Id" uuid NOT NULL,
    "SourceIp" character varying(64),
    "DeviceId" character varying(256),
    "DestinationIp" character varying(64),
    "DestinationPort" integer NOT NULL DEFAULT 0,
    "Protocol" character varying(16),
    "DnsName" character varying(256),
    "BytesOut" bigint NOT NULL DEFAULT 0,
    "BytesIn" bigint NOT NULL DEFAULT 0,
    "PacketsOut" integer NOT NULL DEFAULT 0,
    "WindowSeconds" integer NOT NULL DEFAULT 0,
    "ObservedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    CONSTRAINT "PK_DlpFlowRecords" PRIMARY KEY ("Id")
);
CREATE INDEX IF NOT EXISTS "IX_DlpFlowRecords_ObservedAt" ON public."DlpFlowRecords" ("ObservedAt");
CREATE INDEX IF NOT EXISTS "IX_DlpFlowRecords_SourceIp_ObservedAt" ON public."DlpFlowRecords" ("SourceIp", "ObservedAt");

CREATE TABLE IF NOT EXISTS public."DlpEvidenceRequests" (
    "Id" uuid NOT NULL,
    "CapsuleId" character varying(128),
    "EventId" uuid NOT NULL,
    "FindingId" uuid,
    "RequestedBy" character varying(128),
    "Reason" character varying(1024),
    "AuthenticatedAs" character varying(128),
    "Status" character varying(32),
    "ApprovedBy" character varying(128),
    "ApprovedAt" timestamp with time zone,
    "RejectReason" character varying(512),
    "ReviewedBy" character varying(128),
    "ExportedBy" character varying(128),
    "ExportedAt" timestamp with time zone,
    "CapsuleJson" text,
    "CapsuleSha256" character varying(128),
    "Signature" text,
    "SignatureAlgo" character varying(64),
    "TimestampSource" character varying(128),
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    CONSTRAINT "PK_DlpEvidenceRequests" PRIMARY KEY ("Id")
);
CREATE INDEX IF NOT EXISTS "IX_DlpEvidenceRequests_Status_CreatedAt" ON public."DlpEvidenceRequests" ("Status", "CreatedAt");

-- 5. 语义研判与网络侧发现表
CREATE TABLE IF NOT EXISTS public."SemanticAdjudicationAudits" (
    "Id" uuid NOT NULL,
    "IncidentId" uuid,
    "Mode" character varying(32),
    "Model" character varying(128),
    "EndpointHost" character varying(256),
    "PayloadMasked" text,
    "PayloadHash" character varying(128),
    "VerdictJson" text,
    "Status" character varying(32),
    "Error" character varying(1024),
    "LatencyMs" integer NOT NULL DEFAULT 0,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    CONSTRAINT "PK_SemanticAdjudicationAudits" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS public."ActiveVerificationRecords" (
    "Id" uuid NOT NULL,
    "IncidentId" uuid,
    "AssetId" uuid,
    "AssetName" character varying(256),
    "Verdict" character varying(64),
    "SignalsJson" text,
    "Reason" character varying(1024),
    "Trigger" character varying(128),
    "Margin" numeric NOT NULL DEFAULT 0,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    CONSTRAINT "PK_ActiveVerificationRecords" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS public."NetworkObservedHosts" (
    "Id" uuid NOT NULL,
    "Ip" character varying(64),
    "Mac" character varying(64),
    "SwitchHost" character varying(256),
    "IfIndex" integer NOT NULL DEFAULT 0,
    "IsLive" boolean NOT NULL DEFAULT TRUE,
    "FirstSeenAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "LastSeenAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    CONSTRAINT "PK_NetworkObservedHosts" PRIMARY KEY ("Id")
);
CREATE INDEX IF NOT EXISTS "IX_NetworkObservedHosts_IsLive" ON public."NetworkObservedHosts" ("IsLive");
CREATE INDEX IF NOT EXISTS "IX_NetworkObservedHosts_LastSeenAt" ON public."NetworkObservedHosts" ("LastSeenAt");
CREATE INDEX IF NOT EXISTS "IX_NetworkObservedHosts_SwitchHost_Ip" ON public."NetworkObservedHosts" ("SwitchHost", "Ip");

CREATE TABLE IF NOT EXISTS public."BusinessInterfaceUsages" (
    "Id" uuid NOT NULL,
    "BusinessSystemId" uuid NOT NULL,
    "BusinessComponentId" uuid,
    "UsageType" character varying(64),
    "InterfaceCode" character varying(128),
    "Enabled" boolean NOT NULL DEFAULT TRUE,
    "EvidenceSource" character varying(64),
    "FirstSeen" timestamp with time zone NOT NULL DEFAULT NOW(),
    "LastSeen" timestamp with time zone NOT NULL DEFAULT NOW(),
    CONSTRAINT "PK_BusinessInterfaceUsages" PRIMARY KEY ("Id")
);
CREATE INDEX IF NOT EXISTS "IX_BusinessInterfaceUsages_BusinessSystemId" ON public."BusinessInterfaceUsages" ("BusinessSystemId");
CREATE INDEX IF NOT EXISTS "IX_BusinessInterfaceUsages_InterfaceCode" ON public."BusinessInterfaceUsages" ("InterfaceCode");

-- 6. 现有表的字段补充
ALTER TABLE public."Incidents" ADD COLUMN IF NOT EXISTS "ResolvedReason" character varying(512);
ALTER TABLE public."ErrorClusters" ADD COLUMN IF NOT EXISTS "LastAlertedAt" timestamp with time zone;
ALTER TABLE public."ErrorClusters" ADD COLUMN IF NOT EXISTS "MatchedBy" character varying(32);
ALTER TABLE public."ErrorClusters" ADD COLUMN IF NOT EXISTS "ObservedHosts" character varying(256);

